def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    candidates = []
    for color in range(10):
        pts = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == color and color != bg]
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                if abs(r2 - r1) != 1 or abs(c2 - c1) != 1:
                    continue
                if r1 > r2:
                    r1, r2, c1, c2 = r2, r1, c2, c1
                dr, dc = 1, c2 - c1
                # Extend from the lower of the two diagonal cells.
                r, c = r2 + dr, c2 + dc
                cells = []
                while 0 <= r < h and 0 <= c < w and grid[r][c] == bg:
                    cells.append((r, c))
                    r += dr
                    c += dc
                if cells:
                    candidates.append((len(cells), color, cells))

    out = [row[:] for row in grid]
    if candidates:
        _, color, cells = max(candidates)
        for r, c in cells:
            out[r][c] = color
    return out
